const listTasks = `-- name: ListTasks :many

SELECT t.id, t.no, t.title, t.description, t.creator_id, t.assignee_id, t.handed_back_from_id, t.handed_back_at, t.branch_id, t.class_id, t.student_id, t.care_milestone, t.big_test_id, t.merchandise_item_id, t.lesson_session, t.time_slot_category, t.task_type, t.kind, t.frequency, t.due_date, t.due_time, t.status, t.completion_note, t.completion_proof_url, t.completion_proof_file_id, t.blocked_reason, t.rejection_reason, t.confirmed_by, t.confirmed_at, t.completed_at, t.sla_breached_at, t.version, t.created_at, t.updated_at,
       a.full_name AS assignee_name, c.full_name AS creator_name, hb.full_name AS handed_back_from_name,
       count(*) OVER () AS total
FROM ops.work_tasks t
LEFT JOIN iam.users a ON a.id = t.assignee_id
JOIN iam.users c ON c.id = t.creator_id
LEFT JOIN iam.users hb ON hb.id = t.handed_back_from_id
WHERE (CASE WHEN $1::text = 'assigned' THEN t.creator_id = $2::uuid ELSE t.assignee_id = $2::uuid END)
  AND ($3::text = 'all'
       OR t.creator_id = $2::uuid OR t.assignee_id = $2::uuid OR t.handed_back_from_id = $2::uuid
       OR ($3::text = 'branch' AND (t.branch_id = ANY ($4::uuid[]) OR EXISTS (
             SELECT 1 FROM iam.user_branches ub WHERE ub.user_id = t.assignee_id AND ub.is_primary
               AND ub.branch_id = ANY ($4::uuid[])))))
  AND ($5::text IS NULL OR t.status = $5::text)
  AND ($6::text IS NULL OR t.task_type = $6::text)
  AND ($7::date IS NULL OR t.due_date >= $7::date)
  AND ($8::date IS NULL OR t.due_date <= $8::date)
  AND ($9::uuid IS NULL OR t.assignee_id = $9::uuid)
  AND ($10::text IS NULL OR t.title ILIKE $10::text
       OR t.description ILIKE $10::text OR a.full_name ILIKE $10::text)
ORDER BY CASE t.status
             WHEN 'overdue' THEN 1 WHEN 'blocked' THEN 2 WHEN 'pending_confirmation' THEN 3
             WHEN 'in_progress' THEN 4 WHEN 'new' THEN 5 WHEN 'completed' THEN 6 WHEN 'canceled' THEN 7 ELSE 8
         END, t.created_at DESC, t.id DESC
LIMIT $12::int OFFSET $11::int
`

